package vn.codegym.salesinventory.controller;
import jakarta.servlet.http.*;import java.time.*;import vn.codegym.salesinventory.service.*;import vn.codegym.salesinventory.dao.Sql;import vn.codegym.salesinventory.validation.CatalogValidation;
public final class PricingServlet extends PortalServlet {
 private LocalDate date(HttpServletRequest r,String key){try{return LocalDate.parse(value(r,key));}catch(Exception e){throw new IllegalArgumentException("Ngày hiệu lực không hợp lệ.");}}
 protected void get(HttpServletRequest r,HttpServletResponse s)throws Exception{var service=new PricingService(source());r.setAttribute("groups",service.groups());var versions=service.versions(actor(r).id());r.setAttribute("versions",versions);if(!value(r,"id").isEmpty()){long id=number(r,"id");r.setAttribute("edit",versions.stream().filter(v->Sql.id(v.get("id"))==id).findFirst().orElseThrow(()->new IllegalArgumentException("Không tìm thấy phiên bản.")));r.setAttribute("items",service.items(actor(r).id(),id));}r.setAttribute("products",new ProductService(source()).list(actor(r).id(),value(r,"q"),null,"",1));r.setAttribute("today",LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")));if(value(r,"action").equals("quote")){var q=service.quote(actor(r).id(),number(r,"group"),number(r,"product"),date(r,"date"));r.setAttribute("quote","Giá bán: "+q.sellingPrice()+"; giá sàn: "+q.floorPrice()+"; phiên bản: "+q.versionId());}view(r,s,"pricing/prices");}
 protected void post(HttpServletRequest r,HttpServletResponse s)throws Exception{var service=new PricingService(source());long id=value(r,"id").isEmpty()?0:number(r,"id");switch(value(r,"action")){case "create"->id=service.create(actor(r).id(),number(r,"group"),value(r,"name"),date(r,"from"),date(r,"to"),value(r,"parent").isEmpty()?null:number(r,"parent"));case "edit"->service.edit(actor(r).id(),id,number(r,"revision"),value(r,"name"),date(r,"from"),date(r,"to"));case "item"->service.saveItem(actor(r).id(),id,number(r,"product"),CatalogValidation.decimal(value(r,"selling"),4,false),CatalogValidation.decimal(value(r,"floor"),4,false));case "deleteItem"->service.deleteItem(actor(r).id(),id,number(r,"item"));default->throw new IllegalArgumentException("Thao tác không hợp lệ.");}redirect(r,s,"/pricing/lists?id="+id);}
}

